#!/usr/bin/env python3
import curses
import os
import sys
import subprocess
import tomli
from datetime import datetime

class GitManager:
    def __init__(self):
        try:
            self.repo_path = subprocess.run(['git', 'rev-parse', '--show-toplevel'], capture_output=True, text=True).stdout.strip()
            self.repo_name = os.path.basename(self.repo_path)
        except:
            self.repo_path = os.getcwd()
            self.repo_name = os.path.basename(os.getcwd())

    def run(self, args):
        try:
            result = subprocess.run(['git'] + args, capture_output=True, text=True)
            return result.stdout
        except:
            return ""

    def get_commits(self):
        out = self.run(['log', '--all', '--topo-order', '--format=%H %P%n%D%n%s%n%at%n%an%n%ae'])
        if not out: return []
        lines = out.splitlines()
        commits = []
        for i in range(0, len(lines), 6):
            if i + 5 >= len(lines): break
            h_p = lines[i].split()
            commits.append({
                'hash': h_p[0],
                'parents': h_p[1:],
                'refs': self.parse_refs(lines[i+1]),
                'subject': lines[i+2],
                'timestamp': int(lines[i+3]),
                'author_name': lines[i+4],
                'author_email': lines[i+5]
            })
        return commits

    def parse_refs(self, refs_str):
        if not refs_str: return []
        refs = []
        for ref in refs_str.split(','):
            ref = ref.strip()
            if ' -> ' in ref: ref = ref.split(' -> ')[1]
            if ref.startswith('tag: '): ref = ref[5:]
            refs.append(ref)
        return refs

    def get_commit_detail(self, h):
        return self.run(['show', '-s', '--format=%H%n%an%n%ae%n%ad%n%P%n%B', '--date=format:%Y-%m-%d %H:%M:%S', h])

    def get_changed_files(self, h):
        out = self.run(['show', '--stat', '--name-status', '--format=', h])
        lines = out.splitlines()
        summary = ""
        files = []
        for line in lines:
            if 'file' in line and 'changed' in line: summary = line.strip()
            elif line and line[0] in 'AMDR' and '\t' in line:
                parts = line.split('\t')
                if len(parts) >= 2: files.append({'status': parts[0], 'file': parts[1]})
        return summary, files

class GraphRenderer:
    def __init__(self, commits):
        self.commits = commits
        self.colors = [12, 2, 5, 3, 1, 6, 4]

    def render(self):
        lines = []
        columns = []
        for idx, commit in enumerate(self.commits):
            h = commit['hash']
            merge_indices = [i for i, v in enumerate(columns) if v == h]
            if len(merge_indices) > 1:
                left = min(merge_indices)
                right = max(merge_indices)
                m_idx = max((i for i, v in enumerate(columns) if v is not None), default=right)
                res = [" "] * (2 * m_idx + 2)
                cols_color = [0] * (2 * m_idx + 2)
                for i, v in enumerate(columns):
                    if v is None: continue
                    if i in merge_indices:
                        res[2*i+1] = "├" if i == left else ("╯" if i == right else "┴")
                        cols_color[2*i+1] = self.colors[left % 7]
                    else:
                        res[2*i+1] = "│"
                        cols_color[2*i+1] = self.colors[i % 7]
                for i in range(2 * left + 2, 2 * right + 1):
                    if res[i] == " ":
                        res[i] = "─"
                        cols_color[i] = self.colors[left % 7]
                lines.append(("".join(res), None, cols_color))
                new_cols = []
                for i, v in enumerate(columns):
                    if i in merge_indices: new_cols.append(h if i == left else None)
                    else: new_cols.append(v)
                columns = new_cols

            if h not in columns:
                try: col_idx = columns.index(None); columns[col_idx] = h
                except ValueError: col_idx = len(columns); columns.append(h)
            else: col_idx = columns.index(h)

            parents = commit['parents']
            for p in parents[1:]:
                if p not in columns:
                    try: p_idx = columns.index(None); columns[p_idx] = p
                    except ValueError: columns.append(p)

            m_idx = max((i for i, v in enumerate(columns) if v is not None), default=col_idx)
            res = [" "] * (2 * m_idx + 2)
            cols_color = [0] * (2 * m_idx + 2)
            for i, v in enumerate(columns):
                if v is None: continue
                if i == col_idx: res[2*i+1] = "●"; cols_color[2*i+1] = self.colors[i % 7]
                else: res[2*i+1] = "│"; cols_color[2*i+1] = self.colors[i % 7]

            for i in range(1, len(parents)):
                p_idx = columns.index(parents[i])
                for j in range(2 * col_idx + 2, 2 * p_idx + 1):
                    res[j] = "─"; cols_color[j] = self.colors[col_idx % 7]
                res[2 * p_idx + 1] = "╮"; cols_color[2 * p_idx + 1] = self.colors[col_idx % 7]

            lines.append(("".join(res), h, cols_color))
            if not parents: columns[col_idx] = None
            else: columns[col_idx] = parents[0]
        return lines

class KeifuApp:
    def __init__(self, stdscr):
        self.stdscr = stdscr
        self.gm = GitManager()
        self.refresh()
        self.selected_idx = 0
        self.scroll_top = 0
        self.setup_colors()
        self.current_branch = self.gm.run(['rev-parse', '--abbrev-ref', 'HEAD']).strip()
        self.help_open = False
        self.search_open = False
        self.search_query = ""
        self.search_results = []
        self.search_idx = 0
        curses.curs_set(0)
        self.stdscr.nodelay(True)
        self.run()

    def refresh(self):
        self.commits = self.gm.get_commits()
        self.graph_lines = GraphRenderer(self.commits).render()
        self.commit_to_line = {h: i for i, (s, h, c) in enumerate(self.graph_lines) if h}
        self.all_branches = [line.strip() for line in self.gm.run(['branch', '-a', '--format=%(refname:short)']).splitlines() if line.strip()]

    def setup_colors(self):
        curses.start_color()
        curses.use_default_colors()
        for i, c in enumerate([12, 2, 5, 3, 1, 6, 4]): curses.init_pair(i+1, c, -1)
        curses.init_pair(8, 8, -1)
        curses.init_pair(9, 0, 8)
        curses.init_pair(10, 0, 5)
        curses.init_pair(11, 0, 2)
        curses.init_pair(12, 0, 6)

    def draw(self):
        self.stdscr.erase()
        h, w = self.stdscr.getmaxyx()
        if self.selected_idx < self.scroll_top: self.scroll_top = self.selected_idx
        elif self.selected_idx >= self.scroll_top + h - 10: self.scroll_top = self.selected_idx - (h - 11)

        # Commits
        win = self.stdscr.derwin(h-9, w, 0, 0)
        win.attron(curses.color_pair(8)); win.box(); win.addstr(0, 2, " Commits "); win.attroff(curses.color_pair(8))
        for i in range(h-11):
            idx = self.scroll_top + i
            if idx >= len(self.graph_lines): break
            s, hash, cols = self.graph_lines[idx]
            is_sel = (idx == self.selected_idx)
            win.move(i+1, 1)
            for j, char in enumerate(s):
                if is_sel: attr = curses.color_pair(9)
                else: attr = curses.color_pair(cols[j]) if cols[j] else curses.A_NORMAL
                if char == "●" and hash:
                    c = next(c for c in self.commits if c['hash'] == hash)
                    if self.current_branch in c['refs']: char = "◉"
                try: win.addstr(char, attr)
                except: break
            if hash:
                c = next(c for c in self.commits if c['hash'] == hash)
                l_start = max(12, len(s) + 2)
                label = f"[{c['refs'][0]}] " if c['refs'] else ""
                win.addstr(i+1, l_start, f"{label}{c['subject'][:w-l_start-30]:<{w-l_start-30}} {datetime.fromtimestamp(c['timestamp']).strftime('%Y-%m-%d')}  {c['author_name'][:8]:<8}  {hash[:7]}", curses.color_pair(9) if is_sel else curses.A_NORMAL)
            elif is_sel:
                try: win.addstr(i+1, len(s)+1, " " * (w-len(s)-2), curses.color_pair(9))
                except: pass

        curr_h = self.graph_lines[self.selected_idx][1]
        if curr_h:
            # Detail
            dwin = self.stdscr.derwin(8, w//2, h-9, 0)
            dwin.attron(curses.color_pair(8)); dwin.box(); dwin.addstr(0, 2, " Commit Detail "); dwin.attroff(curses.color_pair(8))
            detail = self.gm.get_commit_detail(curr_h).splitlines()
            if len(detail) >= 6:
                dwin.addstr(1, 1, f"Commit: {detail[0][:w//2-10]}", curses.A_BOLD)
                dwin.addstr(2, 1, f"Author: {detail[1]} <{detail[2]}>")
                dwin.addstr(3, 1, f"Date:   {detail[3]}")
                dwin.addstr(4, 1, f"Parent: {detail[4][:w//2-10]}")
                dwin.addstr(6, 1, "\n".join(detail[5:])[:7*(w//2-2)])
            # Files
            fwin = self.stdscr.derwin(8, w-w//2, h-9, w//2)
            fwin.attron(curses.color_pair(8)); fwin.box(); fwin.addstr(0, 2, " Changed Files "); fwin.attroff(curses.color_pair(8))
            sum, files = self.gm.get_changed_files(curr_h)
            fwin.addstr(1, 1, sum[:w-w//2-2], curses.A_BOLD)
            for i, f in enumerate(files[:5]):
                color = 2 if f['status'] == 'A' else (3 if f['status'] == 'M' else 1)
                fwin.addstr(i+2, 1, f" {f['status']} ", curses.color_pair(color))
                fwin.addstr(f"{f['file'][:w-w//2-10]}")

        # Status
        self.stdscr.move(h-1, 0)
        for t, c in [(f" {self.gm.repo_name} ", 10), (f" {self.current_branch} ", 11), (" j/k ", 12), ("move ", 0), (" Enter ", 12), ("checkout ", 0), (" b ", 12), ("branch ", 0), (" f ", 12), ("fetch ", 0), (" ? ", 12), ("help ", 0), (" q ", 12), ("quit ", 0)]:
            self.stdscr.addstr(t, curses.color_pair(c) | (curses.A_BOLD if c >= 10 else 0))

        if self.help_open:
            hwin = self.stdscr.subwin(15, 50, (h-15)//2, (w-50)//2)
            hwin.box(); hwin.addstr(0, 2, " Help "); hwin.addstr(2, 2, "j/k: Move, g/G: Top/Bottom, ?: Help, q: Quit, /: Search")
        if self.search_open:
            swin = self.stdscr.subwin(10, 40, (h-10)//2, (w-40)//2)
            swin.box(); swin.addstr(0, 2, " Search "); swin.addstr(1, 2, self.search_query + "_")
            for i, r in enumerate(self.search_results[:6]): swin.addstr(i+3, 2, f"▶ {r}", curses.A_REVERSE if i == self.search_idx else 0)

    def run(self):
        while True:
            self.draw(); self.stdscr.refresh()
            try: key = self.stdscr.getch()
            except: key = -1
            if key == -1: curses.napms(50); continue
            if self.help_open:
                if key in [ord('q'), ord('?'), 27]: self.help_open = False
                continue
            if self.search_open:
                if key == 27: self.search_open = False
                elif key == ord('\n') and self.search_results:
                    h = self.gm.run(['rev-parse', self.search_results[self.search_idx]]).strip()
                    if h in self.commit_to_line: self.selected_idx = self.commit_to_line[h]; self.search_open = False
                elif key == curses.KEY_UP: self.search_idx = max(0, self.search_idx-1)
                elif key == curses.KEY_DOWN: self.search_idx = min(len(self.search_results)-1, self.search_idx+1)
                elif key == 127: self.search_query = self.search_query[:-1]; self.search_results = [b for b in self.all_branches if self.search_query.lower() in b.lower()]; self.search_idx = 0
                elif 32 <= key <= 126: self.search_query += chr(key); self.search_results = [b for b in self.all_branches if self.search_query.lower() in b.lower()]; self.search_idx = 0
                continue
            if key == ord('q'): break
            elif key in [ord('j'), curses.KEY_DOWN]: self.selected_idx = min(self.selected_idx+1, len(self.graph_lines)-1)
            elif key in [ord('k'), curses.KEY_UP]: self.selected_idx = max(0, self.selected_idx-1)
            elif key == ord('?'): self.help_open = True
            elif key == ord('/'): self.search_open = True; self.search_query = ""; self.search_results = self.all_branches; self.search_idx = 0
            elif key == ord('\n'):
                h = self.graph_lines[self.selected_idx][1]
                if h:
                    c = next(c for c in self.commits if c['hash'] == h)
                    self.gm.run(['checkout', c['refs'][0] if c['refs'] else h])
                    self.current_branch = self.gm.run(['rev-parse', '--abbrev-ref', 'HEAD']).strip(); self.refresh()

if __name__ == "__main__":
    curses.wrapper(KeifuApp)
